export function daysSinceRoast(roastedOn: string, today: Date): number {
  const [year, month, day] = roastedOn.split("-").map(Number);
  const roastUtc = Date.UTC(year, month - 1, day);
  const todayUtc = Date.UTC(
    today.getUTCFullYear(),
    today.getUTCMonth(),
    today.getUTCDate()
  );
  const diffMs = todayUtc - roastUtc;
  return Math.round(diffMs / (1000 * 60 * 60 * 24));
}

export function isFresh(roastedOn: string, today: Date): boolean {
  const days = daysSinceRoast(roastedOn, today);
  return days >= 0 && days <= 14;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { daysSinceRoast, isFresh } from "../src/freshness.ts";

test("daysSinceRoast and isFresh on day 0", () => {
  const roastedOn = "2026-10-12";
  const today = new Date("2026-10-12");
  assert.equal(daysSinceRoast(roastedOn, today), 0);
  assert.equal(isFresh(roastedOn, today), true);
});

test("daysSinceRoast and isFresh on day 14", () => {
  const roastedOn = "2026-10-12";
  const today = new Date("2026-10-26");
  assert.equal(daysSinceRoast(roastedOn, today), 14);
  assert.equal(isFresh(roastedOn, today), true);
});

test("daysSinceRoast and isFresh on day 15", () => {
  const roastedOn = "2026-10-12";
  const today = new Date("2026-10-27");
  assert.equal(daysSinceRoast(roastedOn, today), 15);
  assert.equal(isFresh(roastedOn, today), false);
});
